steps.script:
GameState.state["factions"]["1"]["detachment"] = "Madcap Meks"
StratagemManager.load_faction_stratagems_for_player(1)
FactionAbilityManager.detect_player_detachment(1)
load("res://scripts/codex/orks/OrkDetachments11e.gd").apply_keyword_grants(1)
SettingsService.set("auto_allocate_wounds", true)
var _ms_U_BLADE_CHAMPION_B = GameState.state.units["U_BLADE_CHAMPION_B"].models
for _i in range(_ms_U_BLADE_CHAMPION_B.size()):
	_ms_U_BLADE_CHAMPION_B[_i]["position"] = {"x": (12.000000 + (float(_i) - float(_ms_U_BLADE_CHAMPION_B.size() - 1) / 2.0) * 1.600000) * 40.0, "y": 38.800000 * 40.0}
var _ms_U_CUSTODIAN_GUARD_D = GameState.state.units["U_CUSTODIAN_GUARD_D"].models
for _i in range(_ms_U_CUSTODIAN_GUARD_D.size()):
	_ms_U_CUSTODIAN_GUARD_D[_i]["position"] = {"x": (8.000000 + (float(_i) - float(_ms_U_CUSTODIAN_GUARD_D.size() - 1) / 2.0) * 1.800000) * 40.0, "y": 42.000000 * 40.0}
for _m in GameState.state.units["U_CUSTODIAN_GUARD_C"].models:
	_m["wounds"] = 99
	_m["current_wounds"] = 99
for _m in GameState.state.units["U_CUSTODIAN_GUARD_D"].models:
	_m["wounds"] = 99
	_m["current_wounds"] = 99
tree.current_scene._recreate_unit_visuals()
return FactionAbilityManager.get_player_detachment(1)

var pa = PhaseManager.get_current_phase_instance().pending_assignments
if pa.is_empty():
	return "none"
for a in pa:
	if str(a.get("target_unit_id", "")) != "U_CUSTODIAN_GUARD_C":
		return str(a.get("target_unit_id", ""))
return "U_CUSTODIAN_GUARD_C"

var t = 0
for m in GameState.get_unit("U_CUSTODIAN_GUARD_D").models:
	if m.get("alive", true):
		t += int(m.get("current_wounds", 0))
var lost = int(GameState.state.meta["_o34_cgd_w"]) - t
return lost >= 1 and lost <= 3
